from fastapi import APIRouter, HTTPException, status
from sqlalchemy.exc import IntegrityError

from app.database import DbSession
from app.models import User
from app.schemas import UserCreate, UserRead

router = APIRouter(prefix="/users", tags=["users"])

# Name generated by the naming convention in models.py.
PHONE_UNIQUE_CONSTRAINT = "uq_users_phone_number"


@router.post("", response_model=UserRead, status_code=status.HTTP_201_CREATED)
def create_user(payload: UserCreate, db: DbSession) -> User:
    user = User(phone_number=payload.phone_number, user_name=payload.user_name)
    db.add(user)
    try:
        db.commit()
    except IntegrityError as exc:
        # No "check first, then insert": two requests could both pass the check.
        # The UNIQUE constraint is the source of truth, so insert and handle the clash.
        db.rollback()
        # exc.orig is the psycopg error; its .diag says which constraint was violated.
        diag = getattr(exc.orig, "diag", None)
        if getattr(diag, "constraint_name", None) == PHONE_UNIQUE_CONSTRAINT:
            raise HTTPException(
                status_code=status.HTTP_409_CONFLICT,
                detail="A user with this phone number already exists",
            ) from exc
        raise
    db.refresh(user)
    return user
